//! diffuse-harvest: Automated fixture generator and dataset extractor.
//!
//! Harvests multi-file git diffs with old and new side snapshots from any
//! repository and emits standard `.json` fixtures conforming to
//! tests/AGENTS.md. The emitted fixture carries the `revision` (range) it was
//! generated from, so a golden can be regenerated byte-for-byte by re-running
//! with the same revision and context width.

use std::{collections::HashMap, env, fs, path::PathBuf, process};

use clap::Parser;
use serde::Serialize;

use diffuse::core::{
    DEFAULT_CONTEXT_LINES,
    git::{load_git_repo, run_git},
};

#[derive(Parser, Debug)]
#[command(
    name = "diffuse-harvest",
    about = "Harvest git diffs into golden fixtures"
)]
struct Args {
    /// Git revision or range (e.g. HEAD~1..HEAD, main..feature, HEAD).
    /// Use the literal `WORKTREE` to diff the working tree against HEAD
    /// (for uncommitted-change fixtures).
    #[arg(default_value = "HEAD~1..HEAD")]
    revision: String,

    /// Change to DIR before doing anything (equivalent to git -C <DIR>).
    #[arg(short = 'C', value_name = "DIR", action = clap::ArgAction::Append)]
    directory: Vec<PathBuf>,

    /// Target repository path (defaults to current directory)
    #[arg(short, long)]
    repo: Option<PathBuf>,

    /// Output fixture path (defaults to stdout)
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Lines of context around changes
    #[arg(short, long, default_value_t = DEFAULT_CONTEXT_LINES)]
    context: usize,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct FixtureOutput {
    diff: String,
    new_content: HashMap<String, String>,
    old_content: HashMap<String, String>,
    /// The revision (or range) this fixture was harvested from; `WORKTREE`
    /// records the working tree against `HEAD`.
    revision: String,
}

fn main() {
    let args = Args::parse();

    for dir in &args.directory {
        if let Err(e) = env::set_current_dir(dir) {
            eprintln!(
                "diffuse-harvest: cannot change directory to '{}': {e}",
                dir.display()
            );
            process::exit(1);
        }
    }

    let repo_root = args
        .repo
        .unwrap_or_else(|| env::current_dir().expect("valid current dir"));

    // `WORKTREE` diffs the (uncommitted) working tree against HEAD.
    let worktree = args.revision == "WORKTREE";
    let base_args: Vec<String> = if worktree {
        Vec::new()
    } else {
        vec![args.revision.clone()]
    };

    let git_res = match load_git_repo(&repo_root, &base_args, &[], false, args.context) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("diffuse-harvest: {e}");
            process::exit(1);
        }
    };

    let revision = if worktree {
        let head = run_git(&repo_root, &["rev-parse", "HEAD"])
            .unwrap_or_default()
            .trim()
            .to_string();
        if head.is_empty() {
            "WORKTREE".to_string()
        } else {
            head
        }
    } else {
        args.revision.clone()
    };

    let fixture = FixtureOutput {
        diff: git_res.diff,
        new_content: git_res.new_content,
        old_content: git_res.old_content,
        revision,
    };

    let json = serde_json::to_string_pretty(&fixture).expect("serialize fixture");

    if let Some(out_path) = args.output {
        if out_path.extension().is_some_and(|ext| ext == "gz") {
            use std::io::Write as _;
            let file = fs::File::create(&out_path).expect("create output file");
            let mut encoder = flate2::write::GzEncoder::new(file, flate2::Compression::best());
            encoder.write_all(json.as_bytes()).expect("write gzip data");
            encoder.finish().expect("finish gzip compression");
        } else {
            fs::write(&out_path, json).expect("write output file");
        }
        eprintln!(
            "Harvested {} files to {}",
            fixture.new_content.len(),
            out_path.display()
        );
    } else {
        println!("{json}");
    }
}
